ALTER TABLE "app_facturacion_cobro_settings" ADD COLUMN "dueReminderDaysBefore" INTEGER NOT NULL DEFAULT 7;
ALTER TABLE "app_facturacion_cobro_settings" ADD COLUMN "dueReminderSubjectTemplate" TEXT NOT NULL DEFAULT 'Aviso: factura {{numero_factura}} vence en {{dias_hasta_vencimiento}} dias — {{cliente}}';
ALTER TABLE "app_facturacion_cobro_settings" ADD COLUMN "dueReminderBodyTemplate" TEXT NOT NULL DEFAULT E'Estimado/a {{contacto_nombre}}:\n\nLe informamos que la factura {{numero_factura}} correspondiente al periodo {{periodo}} por un monto de {{total}} vence el {{fecha_vencimiento}} (faltan {{dias_hasta_vencimiento}} dia(s) para el vencimiento).\n\nAgradecemos adelantar las gestiones de pago correspondientes para evitar retrasos.\n\nEste mensaje fue enviado automaticamente desde Syntra Dynamics.';
